add(58,'The Knox County Area Partnership supports business recruitment, expansion and entrepreneurship in Galesburg and Knox County, Illinois.','Economic development nonprofit','Nonprofit / tax-exempt','https://www.knoxpartnership.com/','The filing has conflicting city/state fields (Knoxville, TN), but its street address 200 East Main St and ZIP 61401 match the Galesburg organization. Exact IRS name and address match EIN 37-1356170. Preserve original filing location as disclosed; the researched organization is in Illinois.',lda(58)+[('https://www.knoxpartnership.com/about-us/','Official page identifies Galesburg/Knox County Illinois economic-development services and 501(c)(6) nonprofit status.'),('https://www.irs.gov/pub/irs-soi/eo2.csv','IRS record EIN 371356170 matches exact organization name and 200 E Main St Ste 200, Galesburg IL 61401.')],'confirmed')
add(81,'Komal Patel is listed as an individual lobbying client in a federal disclosure.','Individual','Not applicable','','The registration lists Coral Springs, Florida. No independently verified biography or professional affiliation was established; do not attach information about people sharing this name. Corporate ownership categories and company logos are not applicable.',lda(81),'unresolved')
add(90,'Konya Mining operates and develops industrial and critical-mineral mines, supplying silica sand and other materials.','Mining company','Private company','https://konyamining.com/','The site uses Konya Mining Company while the filing says Corporation. Exact street address 304 N Broadway, Coweta OK 74429 matches the registration. Its official site expressly describes the business as privately owned.',lda(90)+[('https://konyamining.com/about/','Official page describes privately owned mining business, products and exact Coweta street address matching registration 301848179.xml.')],'confirmed')
f.write_text(json.dumps(e,ensure_ascii=False,indent=2)+'\n');print('Saved',len(e),'profiles; missing',[(i,x['name']) for i,x in enumerate(a) if x['id'] not in e])
